func _run_tests() -> void:
	var crate := await instantiate_scene("res://crate.tscn") as Node2D
	if not check("crate_load", crate != null, "res://crate.tscn deve caricarsi ed essere istanziata"):
		return

	var hurtbox := find_by_name(crate, "Hurtbox") as Area2D
	if not check("hurtbox", hurtbox != null, "La cassa deve avere un'Hurtbox"):
		return

	var hitbox := Hitbox.new()
	hitbox.damage = 1
	hitbox.collision_layer = 0xFFFFFFFF
	hitbox.collision_mask = 0xFFFFFFFF
	var col := CollisionShape2D.new()
	var shape := RectangleShape2D.new()
	shape.size = Vector2(32, 32)
	col.shape = shape
	hitbox.add_child(col)
	hitbox.position = Vector2(100, 100)
	add_child(hitbox)
	await wait_physics_frames(2)
	hitbox.position = crate.position
	await wait_physics_frames(5)

	check("color_changed", crate.modulate != Color.WHITE, "Dopo il primo colpo la cassa deve modulare il colore")

	# Secondo colpo letale
	var health := find_by_name(crate, "Health") as Health
	if health != null:
		health.take_damage(1)
	await wait_frames(2)
	check("crate_destroyed", crate.is_queued_for_deletion(), "A zero punti vita la cassa deve chiamare queue_free()")
	hitbox.queue_free()
